/**
 * @name Path traversal in file serving
 * @description Serving files based on user input without proper validation can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/aiohttp-path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // User-controlled request data in aiohttp
    exists(DataFlow::AttrRead attr |
      attr.getAttributeName() in ["path", "query_string", "match_info", "query"] and
      source = attr
    )
    or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("aiohttp").getMember("web").getMember("Request").getMember(["match_info", "query"]).getACall() and
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // File path operations
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("pathlib").getMember("Path").getACall() or
        call = API::moduleImport("os").getMember("path").getMember("join").getACall() or
        call = API::builtin("open").getACall()
      ) and
      sink = call.getArg(_)
    )
    or
    // FileResponse constructor
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("aiohttp").getMember("web").getMember("FileResponse").getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from user input $@.", source.getNode(), "user-controlled data"
